// project initialization
namespace SpriteKind {
    export const Collectible = SpriteKind.create()
    export const Goal = SpriteKind.create()
}

// variable set up
let spriteDirection = "down"

// project start
scene.setBackgroundColor(13)
tiles.setCurrentTilemap(tilemap`tilemap1`)

// player sprite code
let playerSprite = sprites.create(assets.image`playerForward`, SpriteKind.Player)
tiles.placeOnTile(playerSprite, tiles.getTileLocation(2, 2))
controller.moveSprite(playerSprite)
playerSprite.setStayInScreen(true)

// projectile sprite code
function createProjectile(direction: string) {
    if (direction == "left") {
        let projectile = sprites.createProjectileFromSprite(assets.image`leftProjectile`, playerSprite, -100, 0)
    } else if (direction == "right") {
        let projectile = sprites.createProjectileFromSprite(assets.image`rightProjectile`, playerSprite, 100, 0)
    } else if (direction == "up") {
        let projectile = sprites.createProjectileFromSprite(assets.image`upProjectile`, playerSprite, 0, -100)
    } else if (direction == "down") {
        let projectile = sprites.createProjectileFromSprite(assets.image`downProjectile`, playerSprite, 0, 100)
    }
}

// collectible sprite code
function placeCollectible() {
    let collectible = sprites.create(assets.image`collectible`, SpriteKind.Collectible)
    tiles.placeOnRandomTile(collectible, assets.tile`grassTile`)
}

while (sprites.allOfKind(SpriteKind.Collectible).length < 2) {
    placeCollectible()
}

sprites.onOverlap(SpriteKind.Player, SpriteKind.Collectible, function (sprite: Sprite, otherSprite: Sprite) {
    otherSprite.follow(sprite)
})

sprites.onOverlap(SpriteKind.Collectible, SpriteKind.Goal, function (sprite: Sprite, otherSprite: Sprite) {
    sprites.destroy(sprite, effects.hearts)
    placeCollectible()
})

// goal sprite code
for (let i = 0; i < 3; i++) {
    let goal = sprites.create(assets.image`goalImage`, SpriteKind.Goal)
    tiles.placeOnRandomTile(goal, assets.tile`grassTile`)
}

// enemy sprite code
game.onUpdateInterval(6000, function () {
    let enemySprite = sprites.create(assets.image`enemyImage`, SpriteKind.Enemy)
    tiles.placeOnRandomTile(enemySprite, assets.tile`grassTile`)
})

// project events
controller.left.onEvent(ControllerButtonEvent.Pressed, function () {
    playerSprite.setImage(assets.image`playerLeft`)
    spriteDirection = "left"
})

controller.right.onEvent(ControllerButtonEvent.Pressed, function () {
    playerSprite.setImage(assets.image`playerRight`)
    spriteDirection = "right"
})

controller.up.onEvent(ControllerButtonEvent.Pressed, function () {
    playerSprite.setImage(assets.image`playerBack`)
    spriteDirection = "up"
})

controller.down.onEvent(ControllerButtonEvent.Pressed, function () {
    playerSprite.setImage(assets.image`playerForward`)
    spriteDirection = "down"
})

controller.A.onEvent(ControllerButtonEvent.Pressed, function () {
    createProjectile(spriteDirection)
})

sprites.onOverlap(SpriteKind.Player, SpriteKind.Enemy, function (sprite: Sprite, otherSprite: Sprite) {
    sprites.destroy(otherSprite)
})

sprites.onOverlap(SpriteKind.Collectible, SpriteKind.Enemy, function (sprite: Sprite, otherSprite: Sprite) {
    sprites.destroy(sprite)
    sprites.destroy(otherSprite)
})

sprites.onOverlap(SpriteKind.Projectile, SpriteKind.Enemy, function (sprite, otherSprite) {
    sprites.destroy(sprite)
    sprites.destroy(otherSprite, effects.spray)
})

